def transform(grid):
    h, w = len(grid), len(grid[0])
    # Fill with the repeating sequence carried by the parallel diagonals.
    # Derive the period from the stripe spacing and use c-r as the phase.
    marks = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                marks.setdefault(c-r, []).append(v)
    period = next(p for p in range(1, h+w+1) if all(
        a == b or (s-t) % p != 0
        for s, av in marks.items() for t, bv in marks.items()
        for a in av for b in bv))
    palette = {}
    for offset, vals in marks.items():
        palette[offset % period] = vals[0]
    out = [[palette.get((c-r) % period, 0) for c in range(w)] for r in range(h)]
    assert len(out) == h and all(len(row) == w for row in out)
    assert all(0 <= v <= 9 for row in out for v in row)
    return out
